// JAH demo program — Scale sanity checks
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function lightYearsToKm(ly){ return ly*9.461e12; }
check("universe diameter in km \u2248 8.8e23", lightYearsToKm(93e9)>8e23, true);
check("age \u00d7 c = 13.8 Gly radius (naive)", 13.8*2, 27.6);
check("expansion makes it 93, not 27.6", 93>27.6, true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

